import { describe, it, expect } from 'vitest'
import {
  skillMatchup,
  matchupMultiplier,
  elementOfSkill,
  categoryOfSkill,
  skillDealsDamage,
  tierFor,
} from '../src/engine/matchup'
import { skillMap } from '../src/data'

// Parity fixtures generated by RUNNING the bot's lib/type-matchup.js.

describe('skillMatchup (bot parity)', () => {
  const fireSkill = skillMap['mage_blazing_flame'] // element fire, mult 1.33
  const physSkill = skillMap['warrior_mighty_rampage'] // element physical, mult 0.98
  const healSkill = skillMap['cleric_golden_aura'] // effects[0].type heal

  it('fire skill vs untyped enemy stays neutral', () => {
    const m = skillMatchup(fireSkill, {})
    expect(m.mult).toBe(1)
    expect(m.tier).toBe('neutral')
    expect(m.info).toBeNull()
  })

  it('base grade comes from effectiveness.json matchups (fire vs grass = 1)', () => {
    const m = skillMatchup(fireSkill, { type: 'grass' })
    expect(m.mult).toBe(1)
    expect(m.element).toBe('fire')
    expect(m.category).toBe('fire')
  })

  it('phys skill vs ghost type = neutral (not in physical row)', () => {
    expect(skillMatchup(physSkill, { type: 'ghost' }).mult).toBe(1)
  })

  it('weakTo multiplies ×1.34 → effective tier', () => {
    const m = skillMatchup(fireSkill, { type: 'fire', weakTo: ['fire'] })
    expect(m.mult).toBe(1.34)
    expect(m.tier).toBe('effective')
    expect(m.text).toBe('✅ The element bites here.')
  })

  it('resistTo multiplies ×0.67 → resisted tier', () => {
    const m = skillMatchup(fireSkill, { type: 'water', resistTo: ['fire'] })
    expect(m.mult).toBe(0.67)
    expect(m.tier).toBe('resisted')
    expect(m.text).toBe('🛡️ The foe resists this element.')
  })

  it('support skills never move damage', () => {
    const m = skillMatchup(healSkill, { type: 'grass', weakTo: ['holy'] })
    expect(m.mult).toBe(1)
    expect(m.element).toBe('holy') // cleric default still classifies
    expect(skillDealsDamage(healSkill)).toBe(false)
  })

  it('grade clamps to [0.5, 2]', () => {
    const both = skillMatchup(fireSkill, { type: 'x', weakTo: ['fire'], resistTo: ['fire'] })
    // 1 × 1.34 × 0.67 = 0.8978 → round2 → 0.9
    expect(both.mult).toBe(0.9)
    expect(both.mult).toBeGreaterThanOrEqual(0.5)
    expect(both.mult).toBeLessThanOrEqual(2)
  })

  it('matchupMultiplier is the shortcut', () => {
    expect(matchupMultiplier(fireSkill, { type: 'fire', weakTo: ['fire'] })).toBe(1.34)
    expect(matchupMultiplier(null, { type: 'grass' })).toBe(1)
  })
})

describe('element classifier (bot parity)', () => {
  it('explicit element wins', () => {
    expect(elementOfSkill({ element: 'void' })).toBe('void')
  })

  it('keyword scan of the name', () => {
    expect(elementOfSkill({ name: 'Frost Nova' })).toBe('ice')
    expect(elementOfSkill({ name: 'Shadow Fang' })).toBe('shadow') // shadow before severing
    expect(elementOfSkill({ name: 'Sacred Flame' })).toBe('holy') // holy before fire
  })

  it('class default when no keyword fires', () => {
    expect(elementOfSkill({ name: 'Stonewall', classId: 'cleric' })).toBe('holy') // keyword wins first
    expect(elementOfSkill({ name: 'Plan', classId: 'mage' })).toBe('arcane')
    expect(elementOfSkill({ name: 'Plan', classId: 'rogue' })).toBe('severing')
  })

  it('total: any input yields a known element', () => {
    expect(elementOfSkill(null)).toBe('arcane')
    expect(elementOfSkill(undefined)).toBe('arcane')
    expect(elementOfSkill({})).toBe('arcane')
  })

  it('category folds elements into the 5 matchup rows', () => {
    expect(categoryOfSkill({ element: 'physical' })).toBe('physical')
    expect(categoryOfSkill({ element: 'earth' })).toBe('physical')
    expect(categoryOfSkill({ element: 'severing' })).toBe('severing')
    expect(categoryOfSkill({ element: 'fire' })).toBe('fire')
    expect(categoryOfSkill({ element: 'holy' })).toBe('holy')
    expect(categoryOfSkill({ element: 'ice' })).toBe('magic')
    expect(categoryOfSkill({ element: 'void' })).toBe('magic')
  })
})

describe('tierFor (bot parity)', () => {
  it.each([
    [2, 'super-effective'],
    [1.75, 'super-effective'],
    [1.34, 'effective'],
    [1.15, 'effective'],
    [1, 'neutral'],
    [0.9, 'neutral'],
    [0.89, 'resisted'],
    [0.6, 'weak'],
    [0.5, 'weak'],
  ])('grade %f → %s', (grade, tier) => {
    expect(tierFor(grade)).toBe(tier)
  })
})
